export function dateField(meta,role='created',explicit){const dates=(meta.fields||[]).filter(field=>field.type==='esriFieldTypeDate');if(explicit!==undefined)return dates.some(field=>field.name===explicit)?explicit:'';const mapped=meta.editFieldsInfo?.[role==='created'?'creationDateField':'editDateField'];if(dates.some(field=>field.name===mapped))return mapped;const names=role==='created'?['created_date','creationdate']:['last_edited_date','editdate'];return dates.find(field=>names.includes(field.name.toLowerCase()))?.name||'';}
export function dateValue(value){return typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=8640000000000000?value:null;}
export function timeInfo(meta,attributes,collectionField,detectedAt=Date.now()){const created=dateField(meta,'created',collectionField),edited=dateField(meta,'edited');const reference=meta.editFieldsInfo?.dateFieldsTimeReference||meta.dateFieldsTimeReference;return {collectedField:created,editedField:edited,collectedAt:created?dateValue(attributes[created]):null,editedAt:edited?dateValue(attributes[edited]):null,detectedAt,dateZoneUnknown:meta.datesInUnknownTimezone===true||String(reference?.timeZone).toLowerCase()==='unknown'};}
export function formatTime(value,unknown=false){if(dateValue(value)===null)return 'Not available';if(unknown)return new Date(value).toISOString().replace('T',' ').replace('Z','')+' (stored value; time zone unknown)';return new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Kigali',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(value))+' Kigali (UTC+02:00)';}
export function collectionAge(value,now=Date.now(),unknown=false){if(dateValue(value)===null||unknown)return '';const seconds=Math.floor((now-value)/1000);if(seconds<0)return 'Recorded time is in the future — check source/device clock';if(seconds<60)return seconds+' seconds ago';if(seconds<3600)return Math.floor(seconds/60)+' minutes ago';if(seconds<86400)return Math.floor(seconds/3600)+' hours ago';return Math.floor(seconds/86400)+' days ago';}
